  @state clipboard = {}  @ 557

# Private functions
  @fn save(clip)  @ 62-64
  @fn load()  @ 66-73
  -- Lanes
  @fn isNoteOn(evt)  @ 78-80
      -- A note-on carries the lane values; a note-off spells itself vel 0.
  @fn laneRest(part)  @ 83-85
      -- Only velocity has a configured resting value; other lanes rest at zero.
  @fn laneValue(part, v)  @ 89-93
      -- vel 0 is a note-off rather than a velocity, so it neither survives the
      -- clamp nor displaces the running value. Other lanes take what they're given.
  @fn carrier(series, seed)  @ 97-103
      -- Step a ppq-sorted series with carry-forward: the value at any ppq is the
      -- last one at or before it, seeded from before the region.
  @fn spannedParts(col, part1, part2)  @ 107-119
      -- The parts a span covered, in column order. The '*' sentinel addresses no
      -- part in particular, so it covers them all.
  @fn collect()  @ 122-241
      @contract  nil if empty; single-col -> {mode='single',parts}; multi-col -> {mode='multi',cols}.  @ 121
  @fn refusePaste(chan, evType, lane, cc, startRow, numRows)  @ 246-253
      -- One footprint cell per destination row, fed to aliases() so a paste covering
      -- >=2 instances of one group is refused in global mode (decision 5). Mirrors the
      -- shiftEvents gate; see design/group-aware-editing.md § Injectivity predicate.
  @fn destCarrier(dstCol, part, startppq, endppq)  @ 257-265
      -- The destination lane's own running value across the region, seeded from
      -- the event before it. Values are snapshotted: their events are about to go.
  @fn emitSustainPA(dstCol, values)  @ 268-277
      @contract  a value on a sustain row becomes PA on its host note; onset rows are the note's own  @ 267
  @fn assignLane(dstCol, part, values, startppq, endppq)  @ 280-294
      @contract  carry-forward over the note-ons in region; vel additionally clears and re-emits PA  @ 279
  @fn replaceLane(dstCol, part, srcField, events, startppq, endppq)  @ 297-311
      @contract  replaces the region's events with the clip's, under the destination's identity and field  @ 296
  @fn pasteNotes(dstCol, events, startppq, endppq)  @ 315-340
      -- see docs/editCursor.md § Clipboard: single vs multi
      @contract  replaces the region's notes; lanes the clip omits take the destination's running value  @ 313
  @fn pasteLanes(clip, dstCol, events, startppq, endppq)  @ 343-365
      @contract  clip parts write into the destination parts from the cursor's onward; incompatible skip  @ 342
  @fn pasteSingle(clip)  @ 369-401
      -- see docs/editCursor.md § Clipboard: single vs multi
      @contract  a clip carrying notes replaces the region's; a lane clip writes into the cursor's lane  @ 367
  @fn pasteMulti(clip)  @ 404-522
      @contract  resolves each clip col against cursor's chan via chanDelta; out-of-range channels and missing destinations skip silently; bails entirely if startType=='note' but cursor isn't on a note col.  @ 403
  @fn pasteClip(clip)  @ 524-529
  @fn trimTop(clip, trim)  @ 533-553
      -- A note whose start row falls within the trimmed band is dropped entirely.
      @contract  mutates clip in place; survives both modes; used by duplicate-up at row 0 to keep selection-following behaviour cumulative  @ 531

